<?php ob_start(); $ctx=$ctx??scan_active_context(); $run=$ctx['run']??null; ?>
<h1>Active scan details</h1>
<div class="card"><h2>Full scan info</h2><?php if(!$ctx['running']): ?><p>No scan is currently running.</p><?php else: ?><table>
<tr><th>Field</th><th>Value</th></tr>
<?php foreach(['scan id'=>$run['id']??'pending','profile'=>$run['profile']??'starting','scope'=>$run['scope_type']??'starting','target'=>$run['scope_value']??'full','PID'=>$ctx['pid']??'n/a','process alive'=>($ctx['pid_alive']?'yes':'no'),'stale'=>($ctx['stale']?'yes':'no'),'progress'=>($ctx['progress']!==null?$ctx['progress'].'%':'unknown'),'current path'=>$run['current_path']??'n/a','heartbeat'=>$run['last_heartbeat_at']??'n/a','heartbeat age'=>isset($ctx['heartbeat_age'])?$ctx['heartbeat_age'].'s':'n/a','elapsed time'=>!empty($run['started_at'])?format_duration(max(0,time()-strtotime($run['started_at']))):'n/a','findings'=>$run['findings_count']??0] as $k=>$v): ?><tr><td><?= e($k) ?></td><td><?= e($v) ?></td></tr><?php endforeach ?>
</table><p><form method="post" action="/scan/stop" style="display:inline"><button class="btn danger">Stop scan</button></form><?php if($ctx['stale']): ?> <form method="post" action="/scan/cleanup-stale" style="display:inline"><button class="btn danger">Cleanup stale scan</button></form><?php endif ?></p><?php endif ?></div>
<?php $content=ob_get_clean(); include base_path('resources/views/layouts/app.php'); ?>
